package ged;

import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public final class CompanyCardParser {
    private CompanyCardParser() {}
    private static final String[] MARKERS={"CADASTRO NACIONAL DA PESSOA JURIDICA","COMPROVANTE DE INSCRICAO E DE SITUACAO CADASTRAL"};
    private static String clean(String v){if(v==null)return "";v=v.trim();if(v.isEmpty())return "";String[] chunks=v.split("\\s{2,}");StringBuilder out=new StringBuilder();for(String ch:chunks){ch=ch.trim();if(ch.isEmpty())continue;String[] toks=ch.split("\\s+");int single=0;for(String t:toks)if(t.length()==1||Arrays.asList(".","-","/","(",")","@").contains(t))single++;if(toks.length>=2&&((double)single/toks.length)>=.55){StringBuilder b=new StringBuilder();for(String t:toks)b.append(t);ch=b.toString();}if(out.length()>0)out.append(' ');out.append(ch.replaceAll("\\s+"," ").trim());}return out.toString().trim();}
    private static String nextValue(List<String> lines,String label){String target=PdfEngine.normalize(label),compact=target.replaceAll("\\s+","");for(int i=0;i<lines.size();i++){String nl=PdfEngine.normalize(lines.get(i)),cl=nl.replaceAll("\\s+","");if(nl.contains(target)||cl.contains(compact)){for(int j=i+1;j<Math.min(lines.size(),i+5);j++){String v=clean(lines.get(j));if(!v.isEmpty())return v;}}}return null;}
    public static String formatCnpj(String value){String d=PdfEngine.digits(value);if(d.length()!=14)return value==null?"":value.trim();return d.substring(0,2)+"."+d.substring(2,5)+"."+d.substring(5,8)+"/"+d.substring(8,12)+"-"+d.substring(12);}
    public static boolean validCnpj(String value){String d=PdfEngine.digits(value);if(d.length()!=14)return false;boolean same=true;for(int i=1;i<d.length();i++)if(d.charAt(i)!=d.charAt(0)){same=false;break;}if(same)return false;int[] w1={5,4,3,2,9,8,7,6,5,4,3,2},w2={6,5,4,3,2,9,8,7,6,5,4,3,2};char d1=calc(d.substring(0,12),w1),d2=calc(d.substring(0,12)+d1,w2);return d.substring(12).equals(""+d1+d2);}
    private static char calc(String base,int[]w){int t=0;for(int i=0;i<w.length;i++)t+=(base.charAt(i)-'0')*w[i];int r=t%11;return (char)('0'+(r<2?0:11-r));}

    public static Map<String,Object> parse(Path path) throws Exception {if(!path.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".pdf"))throw new IllegalArgumentException("O cartão CNPJ deve ser enviado em PDF nesta versão.");PdfEngine.PdfData pd=PdfEngine.extract(path);String text=pd.text;List<String> lines=new ArrayList<String>();for(String l:text.split("\\R")){l=l.trim();if(!l.isEmpty())lines.add(l);}String nt=PdfEngine.normalize(text),compact=nt.replaceAll("\\s+","");int hits=0;for(String mk:MARKERS){String n=PdfEngine.normalize(mk);if(nt.contains(n)||compact.contains(n.replaceAll("\\s+","")))hits++;}
        Matcher m=Pattern.compile("(\\d{2})\\.(\\d{3})\\.(\\d{3})/(\\d{4})-(\\d{2})").matcher(compact);String cnpj="";if(m.find())cnpj=formatCnpj(m.group(1)+m.group(2)+m.group(3)+m.group(4)+m.group(5));
        String legal=nextValue(lines,"NOME EMPRESARIAL");String trade=nextValue(lines,"TÍTULO DO ESTABELECIMENTO");String status=nextValue(lines,"SITUAÇÃO CADASTRAL");String municipality=nextValue(lines,"MUNICÍPIO");String uf=nextValue(lines,"UF");String act=nextValue(lines,"CÓDIGO E DESCRIÇÃO DA ATIVIDADE ECONÔMICA PRINCIPAL");
        legal=clean(legal==null?"":legal).toUpperCase(Locale.ROOT);trade=clean(trade==null?"":trade).toUpperCase(Locale.ROOT);status=clean(status==null?"":status).toUpperCase(Locale.ROOT);municipality=clean(municipality==null?"":municipality).toUpperCase(Locale.ROOT);uf=clean(uf==null?"":uf).toUpperCase(Locale.ROOT);act=clean(act==null?"":act);
        // PDFBox may keep neighboring table columns in the same line. Strip known trailing date/column labels.
        legal=legal.replaceAll("\\s+DATA DE CONSTITUI[CÇ][AÃ]O.*$","").trim(); if(!legal.isEmpty())legal=PdfEngine.safeFolderName(legal);
        List<String> errors=new ArrayList<String>();if(hits<1)errors.add("O PDF não possui os marcadores esperados de um Comprovante de Inscrição e de Situação Cadastral.");if(cnpj.isEmpty())errors.add("CNPJ não encontrado no documento.");else if(!validCnpj(cnpj))errors.add("O CNPJ extraído não passou na validação dos dígitos verificadores.");if(legal.isEmpty())errors.add("Razão social não encontrada no documento.");int confidence=0;if(hits>0)confidence+=25;if(hits>=2)confidence+=10;if(!cnpj.isEmpty()&&validCnpj(cnpj))confidence+=30;if(!legal.isEmpty())confidence+=25;if(!status.isEmpty())confidence+=5;if(!municipality.isEmpty()&&!uf.isEmpty())confidence+=5;if(confidence>100)confidence=100;
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("valid",errors.isEmpty());out.put("confidence",confidence);out.put("errors",errors);out.put("document_type",hits>0?"cartao_cnpj":null);out.put("cnpj",cnpj.isEmpty()?null:cnpj);out.put("legal_name",legal.isEmpty()?null:legal);out.put("trade_name",trade.isEmpty()?null:trade);out.put("status",status.isEmpty()?null:status);out.put("municipality",municipality.isEmpty()?null:municipality);out.put("uf",uf.isEmpty()?null:uf);out.put("main_activity",act.isEmpty()?null:act);out.put("folder",legal.isEmpty()?null:PdfEngine.safeFolderName(legal));out.put("metadata",pd.metadata);out.put("text_chars",text.trim().length());return out;}
}
